#pragma once
#include <stdint.h>
#include "fb.h"
#include "logo.h"

/*
 * Boot artwork for the SWEET shim.
 *
 * The apple is the rainbow artwork (logo.h, generated by mklogo_color.py from
 * the source PNG): a 4-bit palette-indexed bitmap, two pixels per byte, drawn
 * at one framebuffer pixel per bitmap pixel. The palette is the six band
 * colours sampled from the source plus black, so the bands survive the
 * quantisation -- which is the whole point of this artwork.
 *
 * There is no spinner any more: the shim used to animate one, but the kernel
 * owns this framebuffer from the jump on and cannot animate it reliably, so
 * the artwork is a single static frame that the kernel's early console draws
 * once and then leaves alone.
 */

static inline void
draw_boot_scene(void)
{
	fb_rect(0, 0, fb.width, fb.height, BLACK);

	int lx = (fb.width - LOGO_W) / 2;
	int ly = (fb.height - LOGO_H) / 2;

	for (int y = 0; y < LOGO_H; y++) {
		for (int x = 0; x < LOGO_W; x++) {
			int i = logo_pixel(x, y);
			if (i) {
				fb_rect(lx + x, ly + y, 1, 1, logo_palette[i]);
			}
		}
	}
}
